CHECK_EQ(count_distinct_pairs({{5, -1}, {0, -1}, {5, -1}}), 2UL);
CHECK_EQ(count_distinct_pairs({{-4, 7}, {7, -4}}), 2UL);
CHECK_EQ(count_distinct_pairs({}), 0UL);

